    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v1, uint v2, uint v3) public payable {
        c.SetMinSum(v1); if (__ESBMC_reverted()) return;
        uint m1 = c.MinSum(); if (__ESBMC_reverted()) return;
        bool r2;
        c.SetMinSum(v2); bool __rev0 = __ESBMC_reverted(); if (__rev0) { r2 = true; } else { r2 = false; }
        uint m2 = c.MinSum(); if (__ESBMC_reverted()) return;
        bool r3;
        c.SetMinSum(v3); bool __rev1 = __ESBMC_reverted(); if (__rev1) { r3 = true; } else { r3 = false; }
        uint m3 = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(m1 == v1 && ((r2 && m2 == m1) || (!r2 && m2 == v2)) && ((r3 && m3 == m2) || (!r3 && m3 == v3)));
    }

    receive() external payable {}
}

